// === Tab: mySketch ===

let particles = [];
let circles = [];
let squiggliness = 50/100;
let interval;
let margin = 10;
let theEnd = false;
let r = 360;
let noiseFactor;

function setup() {
  createCanvas(1112, 834);
  colorMode(HSB, 150);
  noStroke();

  background(0);
	generateCircles();
  updateParticles();

	squiggliness = 1/random(200, 200);
	noiseFactor = random(200, 100);

  interval = setInterval(updateParticles, 1000);
}

function draw() {
	if (theEnd) {
		noLoop();
	} else {
		for (let p of particles) {
			p.draw();
			p.move();
		}
	}
}

function updateParticles() {
  particles = [];
	let xCenter = width/2;
	let yCenter = height/2;
	let n = r*50;
  for (let i = 0; i < n; i++) {
		let theta = map(i, 0, n, -PI, PI);
    let x_ = xCenter + r*sin(theta);
    let y_ = yCenter + r*cos(theta);
		let s_ = 1;
    particles.push(new Particle(x_, y_, s_));
  }
	r -= 20;
	if (r < 20) {
		clearInterval(interval);
		theEnd = true;
	}
}

function Particle(x_, y_, s_) {
  this.x = x_;
  this.y = y_;
  this.size = 6 * s_;

  this.alpha = 100;
  this.dist = 1;

  this.move = function() {
    var theta = noise(this.x * squiggliness, this.y * squiggliness, r/100)*PI*noiseFactor;
    let v = p5.Vector.fromAngle(theta, this.dist);
    this.x += v.x;
    this.y += v.y;
    //this.dist *= 0.999;
    this.alpha *= 0.99;
		this.size *= 0.99;
  }

  this.draw = function() {
		let d = distanceToCircles(this.x, this.y)*100;
		fill((d*10)%200, 200, 200);
    circle(this.x, this.y, this.size);
  }
}

function generateCircles() {
	let maxCircles = 10;
	var xCenter = width/2;
	var yCenter = height/2;
	for (let i = 0; i < maxCircles; i++) {
		var x_ = xCenter + random(-r, r);
		var y_ = yCenter + random(-r, r);
		let r_ = random(10, 50);
		if (!intersectsWithOtherCircles(x_, y_, r_)) {
			circles.push({x: x_, y: y_, r: r_});
		}
	}
}

function intersectsWithOtherCircles(x_, y_, r_) {
	for (let c of circles) {
		if (dist(c.x, c.y, x_, y_) < c.r + r_ + margin) {
			return true;
		}
	}
	return false;
}

function distanceToCircles(x_, y_) {
	var d = 0;
	for (let c of circles) {
		d += c.r/dist(c.x, c.y, x_, y_)
	}
	return d;
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

